import itertools

def is_polite(n):
    def polite(n):
        return itertools.islice(itertools.islice(
            itertools.islice(
                itertools.permutations([0, 1]),
                max(n-1, 0), ((i-1) % n + i) % n), n
            ), n
        ), (n,)

    ordered = OrderedDict.fromkeys(p polite(n) for n in range(2, 101))
    return list(ordered)[n-1]

