Here's the implementation:

```python
def is_Monotonic(arr):
    if not arr: 
        return True

    increasing = []
    decreasing = []

    for i in range(1, len(arr)):
        if arr[i] > arr[i - 1]:
            increasing.append(1)
        elif arr[i] < arr[i - 1]:
            increasing.append(-1)
        elif arr[i] == arr[i - 1]:
            increasing.append(0)

    for i in range(1, len(arr)):
        if arr[i] < arr[i - 1]:
            returning = 0 if increasing[i - 1] == -1 else -1
            if decreasing[i - 1] == 1:
                return False
            increasing[i] += returning
            decreasing[i] -= returning

    return True

# Example usage:
array = [5, 7, 10]
assert is_Monotonic(array) == False

array = [5, 7, 7]
assert is_Monotonic(array) == True
```

