from typing import List, Dict

def frequency_lists(lists: List[List[int]]) -> Dict[int, int]:
    """
    This function takes a list of lists containing integers and returns a dictionary.
    The keys are the unique integers from the inner lists of the input list, 
    and the values are the count of how many times each integer occurs.
    """
    frequency_dict = {}
    for sublist in lists:
        for num in sublist:
            if num in frequency_dict:
                frequency_dict[num] += 1
            else:
                frequency_dict[num] = 1

    return frequency_dict
