def is_even(x):
    # A number is even if its least significant bit is 0
    return x & 1 == 0

class Solution:
    @staticmethod
    def find_even_pair(nums):
        even_pairs = 0
        for i in range(len(nums)):
            for j in range(i + 1, len(nums)):
                if is_even(nums[i] ^ nums[j]):
                    even_pairs += 1
        return even_pairs

# Function to check the correctness of the solution
def check_solution():
    obj = Solution()
    assert obj.find_even_pair([1, 2, 3]) == 2, "Test case 1 failed"
    assert obj.find_even_pair([30, 14, 33, 30]) == 1, "Test case 2 failed"
    assert obj.find_even_pair([2, 4, 8, 16, 32]) == 4, "Test case 3 failed"
    print("All test cases passed!")

# Running the check function to verify correctness
check_solution()
