```python
import unittest
from solution import multiply_int

def multiply_int(a, b):
    if not isinstance(a, int) or not isinstance(b, int):
        raise TypeError("Inputs must be integers.")

    result = []
    for i in str(a):
        for j in str(b):
            product = int(i) * int(j)
            result.append(product)
            # Swap the digits to get the correct product order
            c, c2 = result.pop(0), result.pop(0)
            if c > c2:
                result.append(c)
                result.append(c2)
            else:
                result.append(c2)
                result.append(c)

    return int(''.join(map(str, result)))

class TestMultiplyInt(unittest.TestCase):
    def test_case_1(self):
        self.assertEqual(multiply_int(15, 25), 375)
        self.assertEqual(multiply_int(-15, 25), -375)
        self.assertEqual(multiply_int(150, 25), 3750)

    def test_case_2(self):
        self.assertEqual(multiply_int(123, 2467), 278201)
        self.assertEqual(multiply_int(-123, 2467), 278201)
        self.assertEqual(multiply_int(123, -2467), -278201)

if __name__ == '__main__':
    unittest.main()
